            chatResult.classList.remove('active', 'error');
            chatLoading.classList.add('active');
            btn.disabled = true;

            const formData = new FormData();
            formData.append('prompt', input);

            if (fileInput.files.length > 0) {
                formData.append('image', fileInput.files[0]);
            }

            try {
                const response = await fetch('/chat', {
                    method: 'POST',
                    body: formData
                });

                const data = await response.json();

                if (data.error) {
                    throw new Error(data.error);
                }

                chatResponse.textContent = data.response;
                chatResult.classList.add('active');
            } catch (error) {
                chatResponse.textContent = error.message;
                chatResult.classList.add('active', 'error');
            } finally {
                chatLoading.classList.remove('active');
                btn.disabled = false;
            }
        }

        async function generateImage() {
            const prompt = document.getElementById('image-prompt').value;
            const aspectRatio = document.getElementById('aspect-ratio').value;
            const imageSize = document.getElementById('image-size').value;

            if (!prompt.trim()) {
                alert('Írj be egy képleírást!');
                return;
