                    })
                });

                const data = await response.json();

                if (data.error) {
                    throw new Error(data.error);
                }

                generatedImage.src = 'data:image/png;base64,' + data.image;
                imageResult.classList.add('active');
            } catch (error) {
                const resultText = document.createElement('div');
                resultText.className = 'result-text';
                resultText.textContent = error.message;
                imageResult.innerHTML = '<h3>Hiba</h3>';
                imageResult.appendChild(resultText);
                imageResult.classList.add('active', 'error');
            } finally {
                imageLoading.classList.remove('active');
                btn.disabled = false;
